 * ZSTD_window_init():
 * Initialize a window to empty, starting at index 1 (index 0 is reserved
 * and considered invalid, so that the first input position is always a
 * valid position for a match, even during the first usage of the context).
 * Fixes issue #1241.
 */
MEM_STATIC void ZSTD_window_init(ZSTD_window_t* window) {
    memset(window, 0, sizeof(*window));
    window->base = (BYTE const*)"";
    window->dictBase = (BYTE const*)"";
    window->dictLimit = 1;
    window->lowLimit = 1;
    window->nextSrc = window->base + 1;   /* no need to point anywhere valid, but must not be NULL */
}

